/* =========================== [music library] ============================== *
 * Dynamic Music Library System
 *
 * - Audio manifest is auto-generated by scripts/generate-music-library.mjs
 * - Manifest is loaded from /assets/audio/manifest.js
 * - This file reads window.__AUDIO_MANIFEST__ for track lists
 *
 * Supported formats: mp3, wav, ogg, m4a, flac
 *
 * Adding new songs:
 * 1) Add audio file to assets/audio/<mood> folder
 * 2) Run: node scripts/generate-music-library.mjs
 * 3) OR let GitHub workflow auto-regenerate on push
 *
 * Folder structure:
 * - assets/audio/ (root - categorized as 'others')
 * - assets/audio/moodchill/
 * - assets/audio/moodhappy/
 * - assets/audio/moodsad/
 * - assets/audio/moodsleep/
 * - assets/audio/moodstudy/
 * - (any subfolder works - auto-detected)
 */

const SUPPORTED_AUDIO_EXT = /\.(mp3|wav|ogg|m4a|flac)$/i;

function fileBase(path){
  return (path.split('/').pop() || path).replace(/\.[^/.]+$/,'');
}

function extractTrackInfo(path) {
  const raw = fileBase(path).replace(/_/g, ' ').replace(/\s+/g, ' ').trim();
  let splitIndex = raw.lastIndexOf(' - ');
  let dashLen = 3;
  
  if (splitIndex === -1) {
    let dashes = [];
    for (let i = 0; i < raw.length; i++) {
      if (raw[i] === '-') dashes.push(i);
    }
    
    if (dashes.length > 0) {
      splitIndex = dashes[dashes.length - 1];
      dashLen = 1;
      
      for (let i = dashes.length - 1; i >= 0; i--) {
        let idx = dashes[i];
        if (idx > 0 && idx < raw.length - 1) {
          let before = raw[idx - 1];
          let after = raw[idx + 1];
          let isBeforeUpper = before.toUpperCase() === before && before.toLowerCase() !== before;
          let isAfterUpper = after.toUpperCase() === after && after.toLowerCase() !== after;
          
          if (isBeforeUpper && isAfterUpper) continue;
        }
        splitIndex = idx;
        break;
      }
    }
  }
  
  if (splitIndex !== -1) {
    return {
      title: raw.substring(0, splitIndex).trim(),
      artist: raw.substring(splitIndex + dashLen).trim() || 'Unknown Artist'
    };
  }
  
  return {
    title: raw,
    artist: 'Unknown Artist'
  };
}

function createTrack(mood, file, index){
  let hash = 0;
  for (let i = 0; i < file.length; i++) {
    hash = ((hash << 5) - hash) + file.charCodeAt(i);
    hash |= 0;
  }
  
  const info = extractTrackInfo(file);
  
  return {
    id: `${mood}-${index}-${Math.abs(hash).toString(36)}`,
    mood,
    file,
    title: info.title || 'Unknown Track',
    artist: info.artist
  };
}

function buildMusicLibrary(){
  const byMood = {};
  
  // Get manifest from window (loaded from manifest.js)
  const manifest = (window.__AUDIO_MANIFEST__ && typeof window.__AUDIO_MANIFEST__ === 'object')
    ? window.__AUDIO_MANIFEST__
    : {};
  
  // Parse all categories in manifest
  for (const category of Object.keys(manifest)) {
    const files = (manifest[category] || []).filter(f => SUPPORTED_AUDIO_EXT.test(f));
    const list = files.map((file, index) => createTrack(category, file, index));
    byMood[category] = list; 
  }

  // Ensure all standard MOODS are present
  if (typeof MOODS !== 'undefined' && Array.isArray(MOODS)) {
    for (const mood of MOODS) {
      if (!byMood[mood]) {
        byMood[mood] = [];
      }
    }
  }

  // Freeze all categories
  for (const key of Object.keys(byMood)) {
    byMood[key] = Object.freeze(byMood[key]);
  }

  return Object.freeze(byMood);
}

// Build library after manifest is loaded
const MUSIC_LIBRARY = buildMusicLibrary();
const TRACK_BY_ID = Object.freeze(
  Object.fromEntries(Object.values(MUSIC_LIBRARY).flat().map(t=>[t.id,t]))
);
